import math
X=0.0;Y=0.0;PSI=0.0
done=False;lastp=-10

def _wake(m):
    try:
        wake(m)
    except Exception:
        print(m)

def control(obs):
    global X,Y,PSI,done,lastp
    dt=obs.get('dt',0.1) or 0.1
    v=obs['motion']['v_mps'];st=math.radians(obs['steer_deg'])
    PSI+=v*math.tan(st)/2.75*dt
    X+=v*math.cos(PSI)*dt;Y+=v*math.sin(PSI)*dt
    lc=99.0;rc=99.0
    for name,vw in (obs.get('views') or {}).items():
        if not vw or name=='camera': continue
        try:
            ox,oy=vw['origin']
        except Exception:
            continue
        for p in vw.get('walls') or []:
            try:
                b=float(p[0]);d=float(p[1])
            except Exception:
                continue
            px=ox+d*math.cos(math.radians(b));py=oy+d*math.sin(math.radians(b))
            if -1.0<px<4.6:
                if py>0: lc=min(lc,py-0.925)
                else: rc=min(rc,-py-0.925)
    t=obs.get('t',0)
    if done or X>6.5 or (X>4.5 and Y<-0.9 and abs(math.degrees(PSI))<6):
        if not done:
            done=True
            _wake('forward shunt done X%.1f Y%.1f psi%.0f phi%.0f lc%.2f rc%.2f'%(X,Y,math.degrees(PSI),obs['hitch_deg'],lc,rc))
        return {'steer_deg':0,'speed_mps':0,'look_deg':-23}
    yt=-1.3
    dx=3.0;dy=yt-Y
    c=math.cos(-PSI);s=math.sin(-PSI)
    lx=dx*c-dy*s;ly=dx*s+dy*c
    steer=math.degrees(math.atan2(2*2.75*ly,lx*lx+ly*ly))
    steer=max(-34,min(34,steer))
    if rc<0.3: steer=max(steer,8)
    if lc<0.2: steer=min(steer,-5)
    if t-lastp>1.5:
        lastp=t
        print('t%.1f X%.1f Y%.2f psi%.0f phi%.0f st%.0f lc%.2f rc%.2f'%(t,X,Y,math.degrees(PSI),obs['hitch_deg'],steer,lc,rc))
    return {'steer_deg':steer,'speed_mps':1.0,'look_deg':0}

