import math
R=math.radians
S={'pose':[0.0,0.0,0.0],'pts':{},'gi':0,'gt':0.0,'thf':0.0,'hd':None,'lp':-9,'pr':0,'wk':-99}
SEQ=[-64,150,-35,64,-150,-64,30,64]
def cl(x,a,b):
    return max(a,min(b,x))
def control(obs):
    t=obs['t'];dt=obs.get('dt',0.1) or 0.1
    m=obs['motion'];v=m['v_mps'];sd=obs['steer_deg']
    p=S['pose']
    p[0]+=v*math.cos(p[2])*dt;p[1]+=v*math.sin(p[2])*dt;p[2]+=v*math.tan(R(sd))/2.5*dt
    px,py,yw=p;c=math.cos(yw);s=math.sin(yw)
    def W(x,y):
        return (px+c*x-s*y,py+s*x+c*y)
    for name,vw in (obs.get('views') or {}).items():
        try:
            ox,oy=vw['origin']
            for b,d in vw.get('walls',[]):
                if d>12: continue
                X,Y=W(ox+d*math.cos(R(b)),oy+d*math.sin(R(b)))
                S['pts'][(round(X/0.3),round(Y/0.3))]=(X,Y,t)
        except Exception:
            pass
    if t-S['pr']>0.5:
        S['pr']=t;S['pts']={k:q for k,q in S['pts'].items() if t-q[2]<12}
    hd=obs['head']
    if hd.get('settled') and t-S['gt']>0.5:
        S['gi']=(S['gi']+1)%len(SEQ);S['gt']=t+0.5
    look=SEQ[S['gi']]
    hitch=obs['hitch_deg'];rig=obs['rig'];H=rig['hitch'];RR=rig['trailer_rear']
    vf=rig.get('vehicle_front',3.2)
    if isinstance(vf,(list,tuple)): vf=vf[0]
    try: vf=float(vf)
    except Exception: vf=3.2
    vhw=float(rig.get('vehicle_half_width',1.15) or 1.15)
    thw=float(rig.get('trailer_half_width',1.2) or 1.2)
    vr=vf-3.9
    ux=RR[0]-H[0];uy=RR[1]-H[1];n=math.hypot(ux,uy) or 1;ux/=n;uy/=n
    rc=9.0;lc=9.0;rrc=9.0;rlc=9.0;tc=9.0
    for q in S['pts'].values():
        dx=q[0]-px;dy=q[1]-py
        vx=c*dx+s*dy;vy=-s*dx+c*dy
        if t-q[2]<6:
            if vf-1.2<vx<vf+0.4:
                if vy<0: rc=min(rc,-vy-vhw)
                else: lc=min(lc,vy-vhw)
            elif vr-0.4<vx<vr+0.8:
                if vy<0: rrc=min(rrc,-vy-vhw)
                else: rlc=min(rlc,vy-vhw)
        ax=vx-H[0];ay=vy-H[1]
        al=ax*ux+ay*uy
        if 0.5<al<n+0.3:
            tc=min(tc,abs(-ax*uy+ay*ux)-thw)
    wux=c*ux-s*uy;wuy=s*ux+c*uy
    rx,ry=W(RR[0],RR[1])
    near=[(q[0]-rx,q[1]-ry) for q in S['pts'].values() if abs(q[0]-rx)<10 and abs(q[1]-ry)<10]
    res=[]
    for th in range(-60,61,5):
        a=R(th);dx=wux*math.cos(a)-wuy*math.sin(a);dy=wux*math.sin(a)+wuy*math.cos(a)
        clr=3.0
        for (qx,qy) in near:
            al=qx*dx+qy*dy
            if al<-1 or al>7: continue
            pp=abs(qx*dy-qy*dx)
            if pp<clr: clr=pp
        res.append((th,clr-0.004*abs(th)))
    bv=max(r[1] for r in res)
    bi=min([i for i,r in enumerate(res) if r[1]>=bv-1e-6],key=lambda i:abs(res[i][0]))
    lo=bi
    while lo>0 and res[lo-1][1]>=bv-0.15: lo-=1
    hi=bi
    while hi<len(res)-1 and res[hi+1][1]>=bv-0.15: hi+=1
    ths=(res[lo][0]+res[hi][0])/2.0
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('dist_m') is not None and tg['dist_m']<14:
        b=R(tg['bearing_deg']);d=tg['dist_m']
        TX,TY=W(0.75+d*math.cos(b),d*math.sin(b))
        ex=TX-rx;ey=TY-ry
        tht=math.degrees(math.atan2(wux*ey-wuy*ex,wux*ex+wuy*ey))
        ths=0.3*ths+0.7*cl(tht,-60,60)
    if len(S['pts'])>30: S['thf']+=0.15*(ths-S['thf'])
    th=S['thf']
    hraw=-0.8*th
    yerr=0.0
    if max(lc,rlc)<4 and max(rc,rrc)<4:
        yerr=((lc+rlc)-(rc+rrc))/4.0
        hraw-=6.0*cl(yerr,-1,1)
    hraw=cl(hraw,-35,35)
    rem=(obs.get('progress') or {}).get('remaining',99)
    if rem<7: hraw=cl(hraw,-8,8)
    if S['hd'] is None: S['hd']=cl(hitch,-10,10)
    S['hd']+=cl(hraw-S['hd'],-0.8,0.8)
    hdes=S['hd']
    steer=cl(3.0*(hitch-hdes),-40,40)
    if rrc<0.45: steer=max(steer,cl(10+30*(0.45-rrc)/0.3,10,40))
    if rlc<0.45: steer=min(steer,-cl(10+30*(0.45-rlc)/0.3,10,40))
    if rc<0.45: steer=min(steer,cl(40*(rc-0.15)/0.3,-10,40))
    if lc<0.45: steer=max(steer,-cl(40*(lc-0.15)/0.3,-10,40))
    sp=-0.5
    if min(rc,lc,rrc,rlc,tc)<0.5 or abs(hitch)>30 or rem<5: sp=-0.35
    if t<1.5: sp=0.0
    st=obs.get('status')
    if min(rc,lc,rrc,rlc,tc)<0.15 or abs(hitch)>55 or st=='JACKKNIFED':
        sp=0.0
        if t-S['wk']>8:
            S['wk']=t;wake('halt rc%.2f lc%.2f rrc%.2f rlc%.2f tc%.2f h%.0f hd%.0f rem%.1f'%(rc,lc,rrc,rlc,tc,hitch,hdes,rem))
    if t-S['lp']>1.5:
        S['lp']=t
        print('t%.1f h%.0f hd%.0f th%.0f st%.0f rc%.2f lc%.2f rrc%.2f rlc%.2f tc%.2f y%.2f rem%.1f'%(t,hitch,hdes,th,sd,rc,lc,rrc,rlc,tc,yerr,rem))
    return (steer,sp,look)

