CANDS=[-45,-35,-25,-15,-5,5,15,25,35,45]
def cl(v,a,b):
    return max(a,min(b,v))
def wr(a):
    return (a+math.pi)%(2*math.pi)-math.pi
def tow(px,py):
    c=math.cos(PSI);s=math.sin(PSI)
    return X+px*c-py*s, Y+px*s+py*c
def bd(pts,ox,oy,ang,a,b,c,d):
    ca=math.cos(ang);sa=math.sin(ang);m=9.0
