B1=4.5;RR=19.0;A2=20.5;AC=A2-RR;LD=5.0
def nrm(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a
def cl(x,a,b): return max(a,min(b,x))
def wk(k,m):
    if k not in S['w']:
        S['w'].add(k)
        try: wake(m)
        except Exception: pass
def pts(vw,key='walls'):
    out=[]
    if not vw: return out
    ox,oy=vw['origin']
    for p in vw.get(key) or []:
        try:
            b=float(p[0]);d=float(p[1])
        except Exception:
            continue
        out.append((ox+d*math.cos(Rd(b)),oy+d*math.sin(Rd(b))))
    return out
def W(x,y):
    c=math.cos(S['Yaw']);s=math.sin(S['Yaw'])
    return (S['X']+x*c-y*s,S['Y']+x*s+y*c)
def V(x,y):
    c=math.cos(S['Yaw']);s=math.sin(S['Yaw']);dx=x-S['X'];dy=y-S['Y']
    return (dx*c+dy*s,-dx*s+dy*c)
def control(obs):
    dt=obs.get('dt',0.1) or 0.1
    v=obs['motion']['v_mps'];sd=obs['steer_deg'];h=obs['hitch_deg'];t=obs['t']
    S['X']+=v*math.cos(S['Yaw'])*dt;S['Y']+=v*math.sin(S['Yaw'])*dt
    S['Yaw']+=v*math.tan(Rd(sd))/3.9*dt
    yd=D(S['Yaw'])
    rig=obs['rig'];th=rig['trailer_heading_deg'];hx,hy=rig['hitch']
    vf=rig.get('vehicle_front',5.0)
    try:
        vf=float(vf[0]) if isinstance(vf,(list,tuple)) else float(vf)
    except Exception:
        vf=5.0
    tr=Rd(th);tc=math.cos(tr);ts=math.sin(tr)
    aa,bb=W(hx-10.2*tc,hy-10.2*ts)
    psi=nrm(yd+th+180)
    views=obs.get('views') or {}
    m=S['mem']
    for k in ('direct','periphery','left_mirror','right_mirror','camera'):
        for x,y in pts(views.get(k)):
            wx,wy=W(x,y);m[(round(wx*3),round(wy*3))]=(wx,wy,t)
    for k in list(m.keys()):
        if t-m[k][2]>5.0: del m[k]
    cab=9.0;cabL=9.0;tfl=9.0;tfr=9.0;trr=9.0
    for wx,wy,_ in m.values():
        px,py=V(wx,wy)
        if abs(px)>25 or abs(py)>25: continue
        ex=px-vf if px>vf else (vf-6.2-px if px<vf-6.2 else 0.0)
        ey=max(0.0,abs(py)-1.275);d=math.hypot(ex,ey)
        cab=min(cab,d)
        if py>0: cabL=min(cabL,d)
        a=(px-hx)*tc+(py-hy)*ts;w=-(px-hx)*ts+(py-hy)*tc
        ea=a-1.4 if a>1.4 else (-12.1-a if a<-12.1 else 0.0)
        d=math.hypot(ea,max(0.0,abs(w)-1.275))
        if a>-5:
            if w>0: tfl=min(tfl,d)
            else: tfr=min(tfr,d)
        else: trr=min(trr,d)
    cmin=min(cab,tfl,tfr,trr)
    cam=views.get('camera')
    if cam:
        cs=[W(x,y) for x,y in pts(cam,'target_corners')]
        if len(cs)>=3:
            ca=sum(p[0] for p in cs)/len(cs)
            if abs(ca-A2)<6:
                S['a2']=ca if S['a2'] is None else 0.8*S['a2']+0.2*ca
    if S['mode']=='fwd':
        if v>0: S['fd']+=v*dt
        ye=nrm(yd-180)
        if (S['fd']>=10 and abs(S['Y']-B1)<0.8 and abs(ye)<6 and abs(h)<12 and aa<AC-0.5) or S['fd']>=20:
            S['mode']='rev';S['lt']=t;print('rev start t',round(t,1),'X',round(S['X'],1),'Y',round(S['Y'],2),'yaw',round(yd,1),'h',round(h,1),'A',round(aa,1),round(bb,1))
        else:
            dx=S['X']-8.0-S['X'];dy=B1-S['Y'];c=math.cos(S['Yaw']);s=math.sin(S['Yaw'])
            lx=dx*c+dy*s;ly=-dx*s+dy*c
            al=math.atan2(ly,lx)
            st=cl(D(math.atan(2*3.9*math.sin(al)/8.0)),-25,25)
            if cabL<0.4: st=min(st,-10.0)
            if t-S['last']>2:
                S['last']=t;print('F t',round(t,1),'fd',round(S['fd'],1),'Y',round(S['Y'],2),'yaw',round(yd,1),'h',round(h,1),'cab',round(cab,2),'st',round(st,1))
            return (st,1.0,0)
    if S['mode']=='fwd2':
        if v>0: S['fd']+=v*dt
        if S['fd']>2.5 and abs(h)<30: S['mode']='rev';S['w'].discard('stop')
        else: return (0.0,0.8,90)
    if abs(h)>45:
        S['mode']='fwd2';S['fd']=0.0;wk('jk','hitch >45, pulling fwd');return (0.0,0.8,90)
    if cmin<0.25:
        print('SAFETY t',round(t,1),'cab',round(cab,2),'tfl',round(tfl,2),'tfr',round(tfr,2),'trr',round(trr,2),'h',round(h,1))
        wk('stop','clearance %.2f cab %.2f tfl %.2f tfr %.2f trr %.2f; pulling fwd'%(cmin,cab,tfl,tfr,trr))
        S['mode']='fwd2';S['fd']=0.0;return (0.0,0.8,90)
    ff=0.0;FF=-D(math.atan(10.2/RR))
    if aa<AC and bb<B1+RR:
        e=bb-B1;pd=-D(math.atan(e/LD));reg='L1'
        ff=FF*cl((aa-(AC-2.5))/2.5,0,1)
    elif bb<B1+RR:
        cx=AC;cy=B1+RR
        r=math.hypot(aa-cx,bb-cy);thp=D(math.atan2(bb-cy,aa-cx))
        pd=thp+90+D(math.atan((r-RR)/LD));reg='ARC'
        ff=FF*cl(-thp/12.0,0,1)
    else:
        a2=S['a2'] if S['a2'] is not None else A2
        el=a2-aa;pd=90-D(math.atan(el/LD));reg='L2'
    pd=cl(pd,-40,130)
    ep=nrm(pd-psi)
    hd=cl(ff-1.0*ep,-34,25)
    spd=-0.8
    if tfl<0.8 and h<0: hd=max(hd,h+4);spd=-0.35
    if tfr<0.8 and h>0: hd=min(hd,h-4);spd=-0.35
    st=cl(2.5*(h-hd),-38,38)
    if abs(h-hd)>10: spd=max(spd,-0.6)
    if cabL<0.5: st=max(st,5.0);spd=-0.35
    if trr<0.8 or cab<0.6: spd=-0.35
    if reg=='L2' or (reg=='ARC' and bb>B1+RR-4): look=-41
    else:
        ph=(t-S['lt'])%3.0
        look=90 if ph<2.0 else -41
    if t-S['last']>2:
        S['last']=t
        print('R t',round(t,1),reg,'A',round(aa,1),round(bb,1),'psi',round(psi,1),'pd',round(pd,1),'h',round(h,1),'hd',round(hd,1),'cab',round(cab,2),'tfl',round(tfl,2),'tfr',round(tfr,2),'trr',round(trr,2),'a2',S['a2'] and round(S['a2'],1))
    return (st,spd,look)
